template<>struct Wire<CT_REQUEST> {static Json Encode(const CT_REQUEST& v){Json j=Json::object();j["Magic"]=EncodeWire(v.Magic);j["Version"]=EncodeWire(v.Version);j["Size"]=EncodeWire(v.Size);j["Options"]=EncodeWire(v.Options);return j;}static void Decode(const Json& j,CT_REQUEST& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="Magic")DecodeWire(it.value(),v.Magic);else if(it.key()=="Version")DecodeWire(it.value(),v.Version);else if(it.key()=="Size")DecodeWire(it.value(),v.Size);else if(it.key()=="Options")DecodeWire(it.value(),v.Options);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
